import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const history = [], shown = [], queue = [], notices = [], cancelled = [], deltas = [];
const pending = new Map();
const feed = createProgressFeed({ initialPacket: 'initial', decode: packet => packet === 'slow' || packet === 'fast' ? new Promise(resolve => pending.set(packet, resolve)) : packet });
const stopTelemetry = collectProgressTelemetry(feed, frame => deltas.push(frame));
const ws = createTransferWorkspace({ transport() {}, onCancel: value => cancelled.push(value.attemptId), record: value => queue.push(value), showQueued: value => notices.push(value), recordProgress: value => history.push(value), showProgress: value => shown.push(value) });
const file = { id: 'a', progressFeed: feed };
ws.select(file);
assert.deepEqual(shown.map(x => x.frame), ['initial']);
assert.deepEqual(deltas, []);
feed.emit('slow'); feed.emit('fast');
pending.get('fast')('new'); await Promise.resolve();
pending.get('slow')('old'); await Promise.resolve();
assert.deepEqual(history.map(x => x.frame), ['initial', 'new', 'old']);
assert.deepEqual(shown.map(x => x.frame), ['initial', 'new']);
assert.deepEqual(deltas, ['new', 'old']);
ws.retry();
assert.deepEqual(shown.map(x => x.frame), ['initial', 'new', 'initial']);
ws.hide(); ws.select(file);
assert.equal(shown.at(-1).frame, 'initial');
assert.deepEqual(queue.map(x => Object.keys(x)), queue.map(() => ['fileId','attemptId','visitId','kind']));
ws.dispose(); stopTelemetry();
assert.deepEqual(cancelled, [1,2,3]);
console.log('progress checks passed');
EOF"

